// Cosignr front end. Renders every section from data/artists.json (curated)
// data/sources.json, stats.json, cosigns.json, tours.json, upcoming.json and profiles.json
// (generated by scripts/fetch-*.mjs).

// Trending sort options. Only metrics that at least one artist has are shown as tabs.
// `max` fixes the bar scale (score is out of 100); otherwise bars are relative to the leader.
const METRICS = {
  score:     { tab: "Score",     label: "Cosignr score",     max: 100,
               title: "0–100, from Deezer fans and Last.fm listeners/plays on a log scale" },
  listeners: { tab: "Listeners", label: "Last.fm listeners" },
  plays:     { tab: "Plays",     label: "Last.fm plays" },
  fans:      { tab: "Fans",      label: "Deezer fans" },
};
const INITIAL_COUNT = 4;
const CHIP_COUNT = 4;

// Image sources, in "auto" fallback order (best first).
const SOURCES = {
  press:     { label: "Press kit" },
  wikimedia: { label: "Wikimedia" },
  spotify:   { label: "Spotify" },
  original:  { label: "Original" },
};
const AUTO_ORDER = ["press", "wikimedia", "spotify", "original"];
const DEFAULT_SOURCE = "spotify"; // chosen 2026-10-14 after comparing sources

const store = {
  get(key, fallback) { try { return localStorage.getItem(key) ?? fallback; } catch { return fallback; } },
  set(key, value) { try { localStorage.setItem(key, value); } catch {} },
};

const params = new URLSearchParams(location.search);

const state = {
  metric: "score",
  query: "",
  expanded: false,
  cosigned: new Set(["saba"]),
  source: params.get("src") || store.get("cosignr.imageSource", DEFAULT_SOURCE),
  dev: params.has("dev") || store.get("cosignr.dev", "0") === "1",
};

let DATA, SRC, STATS, COSIGNS, PROFILES, BY_ID;

const $ = sel => document.querySelector(sel);
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const fmt = n => n >= 1e6 ? (n / 1e6).toFixed(1).replace(/\.0$/, "") + "M"
               : n >= 1e3 ? (n / 1e3).toFixed(1).replace(/\.0$/, "") + "k" : String(n);
const initials = name => name.split(/\s+/).filter(w => /^[a-z0-9]/i.test(w)).slice(0, 2).map(w => w[0].toUpperCase()).join("");
// Hand-written hometown wins; otherwise MusicBrainz (born/formed, else based).
const hometown = a => a.hometown || PROFILES.artists[a.id]?.hometown?.text || null;
const icon = id => `<svg class="icon"><use href="#${id}"/></svg>`;

// ---------- images ----------

function sourceFor(artist, name) {
  if (name === "original") return artist.original ? { url: artist.original, thumb: artist.original, credit: null } : null;
  return SRC.artists[artist.id]?.[name] || null;
}

// Returns { src, name } for the current source setting, or { src: null } if unavailable.
function pickImage(artist) {
  if (state.source !== "auto") return { src: sourceFor(artist, state.source), name: state.source };
  for (const name of AUTO_ORDER) {
    const src = sourceFor(artist, name);
    if (src) return { src, name };
  }
  return { src: null, name: "none" };
}

function imageHtml(artist, { size = "large", focus = "center 30%" } = {}) {
  const { src, name } = pickImage(artist);
  if (!src) {
    return `<div class="ph" data-src="none" role="img" aria-label="${esc(artist.name)}">
              <span>${esc(initials(artist.name))}</span>
              ${state.dev ? `<em>No ${esc(SOURCES[state.source]?.label || "")} image</em>` : ""}
            </div>`;
  }
  const url = size === "thumb" ? src.thumb || src.url : src.url;
  const pos = artist.focus?.[name] || focus;
  return `<img src="${esc(url)}" alt="${esc(artist.name)}" loading="lazy" data-src="${name}" style="object-position:${pos}">`;
}

function creditHtml(artist) {
  const { src, name } = pickImage(artist);
  if (!src?.credit) return "";
  const c = src.credit;
  const text = name === "spotify" ? "Image: Spotify" : `Photo: ${c.author} · ${c.license}`;
  return c.source
    ? `<a class="credit" href="${esc(c.source)}" target="_blank" rel="noopener">${esc(text)}</a>`
    : `<span class="credit">${esc(text)}</span>`;
}

// ---------- stats ----------

function metricValue(artist, metric) {
  const s = STATS.artists[artist.id];
  if (!s) return null;
  switch (metric) {
    case "score":     return s.score?.value ?? null;
    case "listeners": return s.excluded.includes("lastfmListeners") ? null : s.lastfm?.listeners ?? null;
    case "plays":     return s.excluded.includes("lastfmPlays") ? null : s.lastfm?.plays ?? null;
    case "fans":      return s.excluded.includes("deezerFans") ? null : s.deezer?.fans ?? null;
  }
}

const availableMetrics = () =>
  Object.keys(METRICS).filter(m => DATA.trending.some(id => metricValue(BY_ID[id], m) != null));

function renderTabs() {
  const metrics = availableMetrics();
  if (!metrics.includes(state.metric)) state.metric = metrics[0];
  $("#metricTabs").innerHTML = `<span>Sort by</span>` + metrics.map(m => `
    <button class="${m === state.metric ? "active" : ""}" type="button" role="tab" aria-selected="${m === state.metric}"
            data-metric="${m}" ${METRICS[m].title ? `title="${esc(METRICS[m].title)}"` : ""}>${esc(METRICS[m].tab)}</button>`).join("");
}

// ---------- cosigns ----------

// For each roster artist: everyone who cosigned them, most famous first (Last.fm listeners),
// then most vouches (features, remixes, tours, touring-band spots, upcoming shows), most songs, most
// recent. Cosigners with unknown fame go last. Songs (cosigns.json), past tours and touring bands
// (tours.json) and upcoming shows (upcoming.json) for the same pair become one chip.
function buildCosignedBy(data, tours, upcoming) {
  const byMbid = Object.fromEntries(DATA.artists.map(a => [a.ids.musicbrainz, a.id]));
  const out = Object.fromEntries(DATA.artists.map(a => [a.id, []]));
  const pairs = new Map();
  const entry = (c, names) => {
    const id = byMbid[c.to];
    if (!id) return null;
    let e = pairs.get(`${c.from}|${c.to}`);
    if (!e) {
      e = { from: c.from, to: c.to, types: [], songs: 0, vouches: 0, tours: 0, first: null, last: null, evidence: [],
            liveEvidence: [], next: null, name: names[c.from].name, fame: STATS.cosigners?.[c.from]?.listeners ?? -1 };
      pairs.set(`${c.from}|${c.to}`, e);
      out[id].push(e);
    }
    return e;
  };
  for (const c of data.cosigns) {
    const e = entry(c, data.artists);
    if (e) Object.assign(e, c);
  }
  for (const t of tours.cosigns) {
    const e = entry(t, tours.artists);
    if (!e) continue;
    e.types = [...new Set([...e.types, ...t.types])];
    e.tours = t.tours;
    e.vouches += t.tours + (t.types.includes("band") ? 1 : 0);
    e.liveEvidence = t.evidence;
    if (t.last && (!e.last || t.last > e.last)) e.last = t.last;
  }
  const today = new Date().toISOString().slice(0, 10);
  for (const u of upcoming.cosigns) {
    if (u.last < today) continue; // Ticketmaster data is only kept until the show has happened
    const e = entry(u, upcoming.artists);
    if (!e) continue;
    e.types = [...new Set([...e.types, "upcoming"])];
    e.vouches += 1;
    e.next = { ...u.next, shows: u.shows };
  }
  for (const list of Object.values(out)) {
    list.sort((x, y) => y.fame - x.fame || y.vouches - x.vouches || y.songs - x.songs || (y.last || "").localeCompare(x.last || ""));
  }
  return out;
}

// Hover text: the strongest evidence leads (upcoming show, then tour, touring band, songs), the rest follow.
function cosignTitle(c, artist) {
  const year = e => (e.date ? ` (${e.date.slice(0, 4)})` : "");
  const lines = [], sources = new Set();
  if (c.next) {
    const when = new Date(c.next.date + "T12:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
    lines.push(`Opening for ${c.name}: ${c.next.tour}, next show ${when}${c.next.city ? " in " + c.next.city : ""}${c.next.shows > 1 ? ` (${c.next.shows} shows)` : ""}`);
    sources.add("Ticketmaster");
  }
  const tour = c.liveEvidence.find(e => e.type === "tour");
  if (tour) {
    lines.push(tour.title ? `${c.name} took ${artist.name} on tour: ${tour.title}${year(tour)}` : `${artist.name} opened for ${c.name}${year(tour)}`);
    if (c.tours > 1) lines.push(`${c.tours} tours`);
  }
  const band = c.liveEvidence.find(e => e.type === "band");
  if (band) lines.push(`${artist.name} played in ${c.name}'s touring band${year(band)}`);
  c.liveEvidence.forEach(e => sources.add(e.source));
  if (c.songs) {
    const e = c.evidence[0];
    if (lines.length) lines.push(`${c.songs} song${c.songs > 1 ? "s" : ""} together`);
    else {
      lines.push((e.type === "feature" ? `${c.name} featured ${artist.name} on “${e.title}”`
                : e.type === "remix"   ? `${artist.name} remixed ${c.name}: “${e.title}”`
                : `${c.name} and ${artist.name}: “${e.title}”`) + year(e));
      if (c.songs > 1) lines.push(`${c.songs} songs together`);
    }
    sources.add("MusicBrainz");
  }
  return lines.join(" · ") + ` · Source: ${[...sources].join(", ")}`;
}

function chipsHtml(artist, { count = CHIP_COUNT, button = true } = {}) {
  const list = COSIGNS[artist.id].slice(0, count);
  if (!list.length) return `<span class="no-cosigns">No cosigns found yet</span>`;
  return list.map((c, i) => {
    const attrs = `class="chip${i === 0 ? " top" : ""}" title="${esc(cosignTitle(c, artist))}"`;
    return button ? `<button ${attrs} type="button" data-chip="${esc(c.name)}">${esc(c.name)}</button>`
                  : `<span ${attrs}>${esc(c.name)}</span>`;
  }).join("");
}

// ---------- sections ----------

function renderFeatured() {
  const [main, ...rest] = DATA.featured.map(f => ({ ...f, a: BY_ID[f.artist] }));
  const tile = (f, cls = "") => {
    const { name } = pickImage(f.a);
    return `
      <article class="tile ${cls}" data-src="${name}">
        ${imageHtml(f.a, { focus: "center 25%" })}
        <span class="badge">${esc(f.label)}</span>
        <div class="overlay">
          <h3>${esc(f.a.name)}</h3>
          <p>${esc([f.a.genre, hometown(f.a)].filter(Boolean).join(" · "))}</p>
          ${cls === "left" ? `<div class="mini-chips">${chipsHtml(f.a, { count: 3, button: false })}</div>` : ""}
        </div>
        <a class="play" href="https://open.spotify.com/artist/${esc(f.a.ids.spotify)}" target="_blank" rel="noopener" aria-label="Listen to ${esc(f.a.name)} on Spotify">${icon("i-play")}</a>
        ${creditHtml(f.a)}
      </article>`;
  };
  $("#gallery").innerHTML = tile(main, "left") + `<div class="right">${rest.map(f => tile(f)).join("")}</div>`;
}

function renderTop() {
  $("#topGrid").innerHTML = DATA.top.map((id, i) => {
    const a = BY_ID[id];
    const { name } = pickImage(a);
    return `
      <article class="top-card" data-src="${name}">
        ${imageHtml(a)}
        <span class="num">${i + 1}</span>
        <div class="overlay">
          <h3>${esc(a.name)}</h3>
          <p>${esc(a.genre)}</p>
        </div>
        ${creditHtml(a)}
      </article>`;
  }).join("");
}

function renderTrending() {
  const m = state.metric;
  const value = a => metricValue(a, m);
  // Artists without a value for this metric sink to the bottom, in curated order.
  const ranked = DATA.trending.map(id => BY_ID[id]).sort((a, b) => (value(b) ?? -1) - (value(a) ?? -1));
  const max = METRICS[m]?.max || value(ranked[0]) || 1;
  const q = state.query.trim().toLowerCase();

  let rows = ranked.map((a, i) => ({ a, rank: i + 1 }));
  if (q) rows = rows.filter(({ a }) => [a.name, a.genre, hometown(a), ...COSIGNS[a.id].map(c => c.name)].some(s => s && s.toLowerCase().includes(q)));
  const visible = q || state.expanded ? rows : rows.slice(0, INITIAL_COUNT);

  const list = $("#trendingList");
  if (!visible.length) {
    list.innerHTML = `<li class="empty">No artists match “${esc(state.query)}”.</li>`;
  } else {
    list.innerHTML = visible.map(({ a, rank }, i) => {
      const on = state.cosigned.has(a.id);
      const v = value(a);
      const caveat = Object.values(a.caveats || {})[0];
      return `
        <li class="artist" style="animation-delay:${i * 40}ms">
          <div class="rank"><b>${v == null ? "–" : rank}</b></div>
          <div class="avatar">${imageHtml(a, { size: "thumb", focus: "center 25%" })}</div>
          <div>
            <h3>${esc(a.name)}</h3>
            <div class="meta">${esc([a.genre, hometown(a)].filter(Boolean).join(" · "))}</div>
            <div class="cosigns">
              <h5>Cosigned by</h5>
              ${chipsHtml(a)}
            </div>
          </div>
          <div class="stat"${v == null && caveat ? ` title="${esc(caveat)}"` : ""}>
            <b>${v == null ? "–" : m === "score" ? v : fmt(v)}</b>
            <small>${v == null ? "No reliable data yet" : esc(METRICS[m].label)}</small>
            <div class="bar"><i style="width:${v == null ? 0 : Math.round(v / max * 100)}%"></i></div>
          </div>
          <button class="cosign-btn${on ? " on" : ""}" type="button" data-cosign="${esc(a.id)}" aria-pressed="${on}">
            ${icon(on ? "i-check" : "i-plus")}${on ? "Cosigned" : "Cosign"}
          </button>
        </li>`;
    }).join("");
  }

  const showMore = $("#showMore");
  showMore.hidden = !!q || rows.length <= INITIAL_COUNT;
  showMore.classList.toggle("open", state.expanded);
  showMore.querySelector("span").textContent = state.expanded ? "Show Less" : `Show More (${rows.length - INITIAL_COUNT})`;
}

function renderCredits() {
  const seen = new Set();
  const items = DATA.artists.map(a => {
    const { src, name } = pickImage(a);
    if (!src?.credit || name === "original") return "";
    const c = src.credit;
    const key = a.id;
    if (seen.has(key)) return "";
    seen.add(key);
    const license = c.licenseUrl ? `<a href="${esc(c.licenseUrl)}" target="_blank" rel="noopener">${esc(c.license)}</a>` : esc(c.license);
    const source = c.source ? ` · <a href="${esc(c.source)}" target="_blank" rel="noopener">source</a>` : "";
    return `<li><b>${esc(a.name)}</b>: ${esc(c.author)} · ${license}${source}</li>`;
  }).filter(Boolean);
  $("#credits").hidden = !items.length;
  $("#creditsList").innerHTML = items.join("");
}

function renderDevPanel() {
  const panel = $("#devPanel");
  panel.hidden = !state.dev;
  if (!state.dev) return;
  const total = DATA.artists.length;
  const count = name => DATA.artists.filter(a => sourceFor(a, name)).length;
  const options = [["auto", "Auto (best available)", total]].concat(
    Object.entries(SOURCES).map(([k, v]) => [k, v.label, count(k)]));
  panel.querySelector(".dev-options").innerHTML = options.map(([k, label, n]) => `
    <label class="${state.source === k ? "on" : ""}">
      <input type="radio" name="imgsrc" value="${k}" ${state.source === k ? "checked" : ""}>
      <span>${esc(label)}</span><small>${n}/${total}</small>
    </label>`).join("");
  panel.querySelector(".dev-meta").textContent =
    `sources.json · ${new Date(SRC.generatedAt).toLocaleString()}\nstats.json · ${new Date(STATS.generatedAt).toLocaleString()}`;
}

function renderAll() {
  document.body.classList.toggle("dev", state.dev);
  renderFeatured();
  renderTabs();
  renderTrending();
  renderTop();
  renderCredits();
  renderDevPanel();
}

// ---------- interactions ----------

let toastTimer;
function toast(msg) {
  const t = $("#toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("show"), 2200);
}

function setDev(on) {
  state.dev = on;
  store.set("cosignr.dev", on ? "1" : "0");
  renderAll();
  toast(on ? "Developer panel on (Shift+D to hide)" : "Developer panel off");
}

function bindEvents() {
  $("#metricTabs").addEventListener("click", e => {
    const btn = e.target.closest("[data-metric]");
    if (!btn) return;
    state.metric = btn.dataset.metric;
    renderTabs();
    renderTrending();
  });

  const searchInput = $("#search");
  searchInput.addEventListener("input", () => { state.query = searchInput.value; renderTrending(); });
  $("#searchForm").addEventListener("submit", e => {
    e.preventDefault();
    state.query = searchInput.value;
    renderTrending();
    $("#trending").scrollIntoView({ behavior: "smooth" });
  });

  $("#trendingList").addEventListener("click", e => {
    const chip = e.target.closest("[data-chip]");
    if (chip) {
      searchInput.value = state.query = chip.dataset.chip;
      renderTrending();
      toast(`Showing artists cosigned by ${chip.dataset.chip}`);
      return;
    }
    const btn = e.target.closest("[data-cosign]");
    if (btn) {
      const id = btn.dataset.cosign;
      const name = BY_ID[id].name;
      if (state.cosigned.delete(id)) toast(`Removed your cosign from ${name} (demo, not saved yet)`);
      else { state.cosigned.add(id); toast(`You cosigned ${name} (demo, not saved yet)`); }
      renderTrending();
    }
  });

  $("#showMore").addEventListener("click", () => { state.expanded = !state.expanded; renderTrending(); });

  document.querySelectorAll("nav a").forEach(a => {
    a.addEventListener("click", e => {
      document.querySelectorAll("nav a").forEach(x => x.classList.toggle("active", x === a));
      if (a.dataset.target === "search") { e.preventDefault(); searchInput.focus(); }
    });
  });

  document.querySelectorAll('a[href="#"]').forEach(a =>
    a.addEventListener("click", e => {
      e.preventDefault();
      if (a.classList.contains("logo")) window.scrollTo({ top: 0, behavior: "smooth" });
      else toast("Coming soon");
    }));

  // Dev panel: Shift+D toggles, or open the page with ?dev
  document.addEventListener("keydown", e => {
    if (e.shiftKey && e.key.toLowerCase() === "d" && !e.target.closest("input, textarea")) setDev(!state.dev);
  });
  $("#devPanel").addEventListener("change", e => {
    if (e.target.name !== "imgsrc") return;
    state.source = e.target.value;
    store.set("cosignr.imageSource", state.source);
    renderAll();
  });
  $("#devClose").addEventListener("click", () => setDev(false));

  bindModal();
}

function bindModal() {
  const modal = $("#modal");
  const MODES = {
    signup: { title: "Create your account", text: "Follow artists and see who they cosign.", submit: "Sign Up",
              sw: 'Already have an account? <a data-switch="login">Log in</a>' },
    login:  { title: "Welcome back", text: "Log in to see your cosigns and follows.", submit: "Log In",
              sw: 'New to Cosignr? <a data-switch="signup">Create an account</a>' },
  };
  let mode = "signup";
  const open = m => {
    mode = m;
    const c = MODES[m];
    $("#modalTitle").textContent = c.title;
    $("#modalText").textContent = c.text;
    $("#modalSubmit").textContent = c.submit;
    $("#modalSwitch").innerHTML = c.sw;
    modal.classList.add("open");
    modal.setAttribute("aria-hidden", "false");
    setTimeout(() => $("#email").focus(), 50);
  };
  const close = () => { modal.classList.remove("open"); modal.setAttribute("aria-hidden", "true"); };

  document.querySelectorAll("[data-modal]").forEach(b => b.addEventListener("click", () => open(b.dataset.modal)));
  modal.addEventListener("click", e => {
    if (e.target === modal || e.target.closest(".close")) close();
    const sw = e.target.closest("[data-switch]");
    if (sw) open(sw.dataset.switch);
  });
  document.addEventListener("keydown", e => { if (e.key === "Escape") close(); });
  $("#authForm").addEventListener("submit", e => {
    e.preventDefault();
    close();
    toast(mode === "signup" ? "Welcome to Cosignr! (demo)" : "Logged in (demo)");
  });
}

// ---------- boot ----------

async function init() {
  try {
    const [artists, sources, stats, cosigns, tours, upcoming, profiles] = await Promise.all([
      fetch("data/artists.json").then(r => r.json()),
      fetch("data/sources.json").then(r => r.json()),
      fetch("data/stats.json").then(r => r.json()),
      fetch("data/cosigns.json").then(r => r.json()),
      fetch("data/tours.json").then(r => r.json()),
      fetch("data/upcoming.json").then(r => r.json()),
      fetch("data/profiles.json").then(r => r.json()),
    ]);
    DATA = artists;
    SRC = sources;
    STATS = stats;
    COSIGNS = buildCosignedBy(cosigns, tours, upcoming);
    PROFILES = profiles;
    BY_ID = Object.fromEntries(DATA.artists.map(a => [a.id, a]));
  } catch (err) {
    console.error(err);
    document.querySelector("main").insertAdjacentHTML("afterbegin",
      `<p class="load-error">Couldn't load artist data. If you opened this file directly, serve the folder instead: <code>python3 -m http.server</code></p>`);
    return;
  }
  bindEvents();
  renderAll();
}

init();
